SourceCode.Declaration:
/// <summary>
/// The handheld's offline item, barcode and variant cache, a page at a time
/// (HSMobileOpsSkuPageSvc/getSkuPage) - see getSkuPage. Replaced a DMF export of the
/// standard released-product entity.
/// </summary>
class HSMobileOpsSkuPageService
{
}

Method.Source:
/// <summary>
/// One page of a master-data feed for the handheld's offline cache - the replacement for the
/// DMF export of the standard released-product entity (hundreds of fields, 6-7 minutes for
/// 18,495 items). Only what the handheld uses, read in key order from indexed tables, a page
/// at a time: the device resumes from NextKey, and with ChangedSinceUtc only what changed.
///
/// Feeds and their row columns:
///   ITEMS    - key ItemId:  [itemId, searchName, inventUnit, purchUnit, salesUnit, batch(0/1), serial(0/1), location(0/1), active(0/1), category]
///              category: the item's retail product hierarchy category as a path from the first
///              level, "Health Care > Vitamins" (blank when it has none). A category move does not
///              touch InventTable, so a delta misses it; the weekly full refresh picks it up.
///              ChangedSinceUtc: InventTable.ModifiedDateTime.
///   BARCODES - key RecId:   [barcode, itemId, qty, unit, configId, sizeId, colorId, styleId, blocked(0/1)]
///              ChangedSinceUtc: InventItemBarcode.ModifiedDateTime.
///   VARIANTS - key RecId:   [itemId, configId, sizeId, colorId, styleId]
///   UNITS    - key ItemId:  [itemId, inventUnit, purchUnit, salesUnit, [[unit, factor, decimals], ...]]
///              Every unit the item can be counted in - its own units, both sides of its
///              product-specific conversions, its barcodes' units - as 1 unit = factor inventory
///              units (HSMobileOpsUnitService::unitsFor's rule), with the unit's decimals.
///              ChangedSinceUtc: the items whose units, product-specific conversions or barcode
///              units changed since - which also carries an item's own unit change, which the
///              ITEMS delta misses (InventTableModule has its own modified date).
///   CATEGORIES - key EcoResProductCategory RecId: [itemId, category]
///              Delta only (a full ITEMS page carries the category): the items whose retail
///              category assignment changed since ChangedSinceUtc - or every assignment when a
///              category of the hierarchy itself changed (renamed, moved), since paths change.
///              No modified date on InventDimCombination - a delta is "RecId after AfterKey";
///              the device's weekly full refresh catches the rest.
///
/// Only what a handheld can use: service items are never sent; a full refresh (no
/// ChangedSinceUtc) also leaves out items whose lifecycle state is not Active and blocked
/// barcodes - the device drops what a full refresh did not send. A delta still sends a change
/// to stopped or blocked, so the device marks it inactive the same day.
///
/// Warehouse: a warehouse that syncs by assortment (Mobile warehouse control) gets only the
/// items of its store's item list, and their barcodes, variants, units and categories; Scope
/// says which. Every other warehouse runs the company-wide queries, unchanged.
/// </summary>
public HSMobileOpsSkuPageResponse getSkuPage(HSMobileOpsSkuPageRequest _request)
{
    HSMobileOpsSkuPageResponse response = new HSMobileOpsSkuPageResponse();
    int          pageSize;
    utcdatetime  since = DateTimeUtil::minValue();

    response.parmSuccess(false);
    response.parmServerUtc(DateTimeUtil::toStr(DateTimeUtil::utcNow()));
    if (!_request || !_request.parmDataAreaId() || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }
    pageSize = _request.parmPageSize();
    if (pageSize <= 0)
    {
        pageSize = 2000;
    }
    pageSize = min(pageSize, 5000);
    if (_request.parmChangedSinceUtc())
    {
        since = DateTimeUtil::parse(_request.parmChangedSinceUtc());
    }

    changecompany (_request.parmDataAreaId())
    {
        // The warehouse's store assortment, or '' for every item - Mobile warehouse control.
        InventLocationId scope = HSMobileOpsWarehouseControl::itemScope(_request.parmWarehouse());
        response.parmScope(scope);
        switch (_request.parmFeed())
        {
            case 'ITEMS':
                HSMobileOpsSkuPageService::itemPage(response, _request.parmAfterKey(), since, pageSize, '', scope);
                break;
            case 'BARCODES':
                HSMobileOpsSkuPageService::barcodePage(response, str2Int64(_request.parmAfterKey()), since, pageSize, 0, scope);
                break;
            case 'VARIANTS':
                HSMobileOpsSkuPageService::variantPage(response, str2Int64(_request.parmAfterKey()), pageSize, scope);
                break;
            case 'CATEGORIES':
                HSMobileOpsSkuPageService::categoryPage(response, str2Int64(_request.parmAfterKey()), since, pageSize, scope);
                break;
            case 'UNITS':
                HSMobileOpsSkuPageService::unitPage(response, _request.parmAfterKey(), since, pageSize, '', scope);
                break;
            default:
                response.parmErrorCode('INVALID_REQUEST');
                response.parmMessage(strFmt('Unknown feed %1', _request.parmFeed()));
                return response;
        }
    }
    response.parmSuccess(true);
    return response;
}

/// <summary>
/// The company's current item snapshot for a device's full re-sync: RowsJson is
/// {"builtAtUtc":..., "files":[{"id","area","part","bytes","rows","sha256"}]}, the parts in
/// build order; each is read with getSkuSnapshotPart (AfterKey = id). ErrorCode NO_SNAPSHOT
/// when there is no Ready build yet: the device then pages through getSkuPage as before.
/// </summary>
public HSMobileOpsSkuPageResponse getSkuSnapshot(HSMobileOpsSkuPageRequest _request)
{
    HSMobileOpsSkuPageResponse response = new HSMobileOpsSkuPageResponse();
    HSMobileOpsSkuSnapshot     snapshot;
    HSMobileOpsSkuSnapshotFile file;
    System.Text.StringBuilder  json = new System.Text.StringBuilder();
    int                        files;

    response.parmSuccess(false);
    response.parmServerUtc(DateTimeUtil::toStr(DateTimeUtil::utcNow()));
    if (!_request || !_request.parmDataAreaId() || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }
    changecompany (_request.parmDataAreaId())
    {
        InventLocationId scope = HSMobileOpsWarehouseControl::itemScope(_request.parmWarehouse());
        response.parmScope(scope);
        // A store whose own snapshot is not built yet: NO_SNAPSHOT, and the device pages
        // through the store's (small) item list at once - it never waits for the nightly job.
        snapshot = HSMobileOpsSkuSnapshot::current(scope);
        if (!snapshot.RecId)
        {
            response.parmErrorCode('NO_SNAPSHOT');
            response.parmMessage('No item snapshot is ready - Mobile item snapshot, Rebuild snapshot now.');
            return response;
        }
        json.Append('{"builtAtUtc":');
        json.Append(HSMobileOpsSkuPageService::jsonStr(DateTimeUtil::toStr(snapshot.BuiltAtUtc)));
        json.Append(',"scope":');
        json.Append(HSMobileOpsSkuPageService::jsonStr(scope));
        json.Append(',"files":[');
        // Area by area, ITEMS first, each in part order (the parts are written side by side,
        // so RecId order is not the order). Not the data itself.
        container areas = HSMobileOpsSkuPageService::snapshotAreas();
        for (int a = 1; a <= conLen(areas); a++)
        {
            str area = conPeek(areas, a);
            while select RecId, Area, Part, Bytes, RowCount, Sha256 from file
                order by file.Part
                where file.SnapshotRecId == snapshot.RecId
                   && file.Area          == area
            {
                if (files)
                {
                    json.Append(',');
                }
                json.Append('{"id":');     json.Append(int642Str(file.RecId));
                json.Append(',"area":');   json.Append(HSMobileOpsSkuPageService::jsonStr(file.Area));
                json.Append(',"part":');   json.Append(int2Str(file.Part));
                json.Append(',"bytes":');  json.Append(int642Str(file.Bytes));
                json.Append(',"rows":');   json.Append(int642Str(file.RowCount));
                json.Append(',"sha256":'); json.Append(HSMobileOpsSkuPageService::jsonStr(file.Sha256));
                json.Append('}');
                files++;
            }
        }
        json.Append(']}');
    }
    response.parmRowsJson(json.ToString());
    response.parmRowCount(files);
    response.parmSuccess(true);
    return response;
}

/// <summary>
/// One part of the current item snapshot (AfterKey = its id from getSkuSnapshot): RowsJson
/// is the ZIP as base64. NOT_FOUND when it is gone - a newer snapshot replaced it; the device
/// then starts its download again.
/// </summary>
public HSMobileOpsSkuPageResponse getSkuSnapshotPart(HSMobileOpsSkuPageRequest _request)
{
    HSMobileOpsSkuPageResponse response = new HSMobileOpsSkuPageResponse();
    HSMobileOpsSkuSnapshotFile file;

    response.parmSuccess(false);
    response.parmServerUtc(DateTimeUtil::toStr(DateTimeUtil::utcNow()));
    if (!_request || !_request.parmDataAreaId() || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }
    changecompany (_request.parmDataAreaId())
    {
        select firstOnly file
            where file.RecId == str2Int64(_request.parmAfterKey());
        if (!file.RecId || !conLen(file.Data))
        {
            response.parmErrorCode('NOT_FOUND');
            return response;
        }
        response.parmRowsJson(System.Convert::ToBase64String(Binary::constructFromContainer(file.Data).getMemoryStream().ToArray()));
        response.parmRowCount(any2Int(file.RowCount));
    }
    response.parmSuccess(true);
    return response;
}

/// <summary>
/// The snapshot areas in the order a device loads them.
/// </summary>
internal static container snapshotAreas()
{
    return ['ITEMS', 'BARCODES', 'VARIANTS', 'UNITS'];
}

/// <summary>
/// The highest item number of the company - the upper bound of a page with none given.
/// </summary>
internal static ItemId lastItemId()
{
    InventTable inventTable;

    select maxof(ItemId) from inventTable;
    return inventTable.ItemId;
}

internal static void itemPage(HSMobileOpsSkuPageResponse _response, ItemId _after, utcdatetime _since, int _pageSize, ItemId _upTo = '', InventLocationId _scope = '')
{
    HSMobileOpsSyncAssortItem           scopeItem;
    InventTable                         inventTable;
    InventTableModule                   inventModule;
    InventTableModule                   purchModule;
    InventTableModule                   salesModule;
    EcoResTrackingDimensionGroupItem    trackingItem;
    EcoResStorageDimensionGroupItem     storageItem;
    EcoResProductCategory               productCategory;
    Map                                 trackingCache = new Map(Types::Int64, Types::Container);
    Map                                 locationCache = new Map(Types::Int64, Types::Integer);
    Map                                 categoryPaths = new Map(Types::Int64, Types::String);
    RefRecId                            hierarchy = HSMobileOpsSkuPageService::retailHierarchy();
    System.Text.StringBuilder           json = new System.Text.StringBuilder();
    container                           tracking;
    int                                 rows;
    ItemId                              last;
    boolean                             more;

    json.Append('[');
    boolean full = _since == DateTimeUtil::minValue();
    // A snapshot task reads only its own range (_after, _upTo]; a plain bound keeps the index seek.
    ItemId upTo = _upTo ? _upTo : HSMobileOpsSkuPageService::lastItemId();

    // A store that syncs by assortment: its item list drives the query, so the store's sync
    // reads only its own items. The same joins and columns as below.
    if (_scope)
    {
        while select ItemId from scopeItem
            order by scopeItem.ItemId
            where scopeItem.Warehouse == _scope
               && scopeItem.ItemId    >  _after
               && scopeItem.ItemId    <= upTo
            join ItemId, NameAlias, ProductLifecycleStateId, Product from inventTable
                where inventTable.ItemId           == scopeItem.ItemId
                   && inventTable.ModifiedDateTime >= _since
                   && inventTable.ItemType         != ItemType::Service
                   && (!full || !inventTable.ProductLifecycleStateId || inventTable.ProductLifecycleStateId == 'Active')
            outer join UnitId from inventModule
                where inventModule.ItemId     == inventTable.ItemId
                   && inventModule.ModuleType == ModuleInventPurchSales::Invent
            outer join UnitId from purchModule
                where purchModule.ItemId     == inventTable.ItemId
                   && purchModule.ModuleType == ModuleInventPurchSales::Purch
            outer join UnitId from salesModule
                where salesModule.ItemId     == inventTable.ItemId
                   && salesModule.ModuleType == ModuleInventPurchSales::Sales
            outer join TrackingDimensionGroup from trackingItem
                where trackingItem.ItemId         == inventTable.ItemId
                   && trackingItem.ItemDataAreaId == inventTable.DataAreaId
            outer join StorageDimensionGroup from storageItem
                where storageItem.ItemId         == inventTable.ItemId
                   && storageItem.ItemDataAreaId == inventTable.DataAreaId
            outer join Category from productCategory
                where productCategory.Product           == inventTable.Product
                   && productCategory.CategoryHierarchy == hierarchy
        {
            if (rows >= _pageSize)
            {
                more = true;
                break;
            }
            if (rows)
            {
                json.Append(',');
            }
            HSMobileOpsSkuPageService::itemRow(json, inventTable, inventModule.UnitId, purchModule.UnitId, salesModule.UnitId,
                HSMobileOpsSkuPageService::trackingFlags(trackingItem.TrackingDimensionGroup, trackingCache),
                HSMobileOpsSkuPageService::locationActive(storageItem.StorageDimensionGroup, locationCache),
                HSMobileOpsSkuPageService::pathOf(productCategory.Category, categoryPaths));
            last = inventTable.ItemId;
            rows++;
        }
        json.Append(']');
        _response.parmRowsJson(json.ToString());
        _response.parmRowCount(rows);
        _response.parmNextKey(last ? last : _after);
        _response.parmHasMore(more);
        return;
    }

    while select ItemId, NameAlias, ProductLifecycleStateId, Product from inventTable
        order by inventTable.ItemId
        where inventTable.ItemId > _after
           && inventTable.ItemId <= upTo
           && inventTable.ModifiedDateTime >= _since
           && inventTable.ItemType != ItemType::Service
           && (!full || !inventTable.ProductLifecycleStateId || inventTable.ProductLifecycleStateId == 'Active')
        outer join UnitId from inventModule
            where inventModule.ItemId     == inventTable.ItemId
               && inventModule.ModuleType == ModuleInventPurchSales::Invent
        outer join UnitId from purchModule
            where purchModule.ItemId     == inventTable.ItemId
               && purchModule.ModuleType == ModuleInventPurchSales::Purch
        outer join UnitId from salesModule
            where salesModule.ItemId     == inventTable.ItemId
               && salesModule.ModuleType == ModuleInventPurchSales::Sales
        outer join TrackingDimensionGroup from trackingItem
            where trackingItem.ItemId         == inventTable.ItemId
               && trackingItem.ItemDataAreaId == inventTable.DataAreaId
        outer join StorageDimensionGroup from storageItem
            where storageItem.ItemId         == inventTable.ItemId
               && storageItem.ItemDataAreaId == inventTable.DataAreaId
        // In the same query (13 Nov): two queries per item were too slow for a million items.
        outer join Category from productCategory
            where productCategory.Product           == inventTable.Product
               && productCategory.CategoryHierarchy == hierarchy
    {
        if (rows >= _pageSize)
        {
            more = true;
            break;
        }
        tracking = HSMobileOpsSkuPageService::trackingFlags(trackingItem.TrackingDimensionGroup, trackingCache);
        if (rows)
        {
            json.Append(',');
        }
        json.Append('[');
        json.Append(HSMobileOpsSkuPageService::jsonStr(inventTable.ItemId)); json.Append(',');
        json.Append(HSMobileOpsSkuPageService::jsonStr(inventTable.NameAlias)); json.Append(',');
        json.Append(HSMobileOpsSkuPageService::jsonStr(inventModule.UnitId)); json.Append(',');
        json.Append(HSMobileOpsSkuPageService::jsonStr(purchModule.UnitId)); json.Append(',');
        json.Append(HSMobileOpsSkuPageService::jsonStr(salesModule.UnitId)); json.Append(',');
        json.Append(conPeek(tracking, 1) ? '1' : '0'); json.Append(',');
        json.Append(conPeek(tracking, 2) ? '1' : '0'); json.Append(',');
        json.Append(HSMobileOpsSkuPageService::locationActive(storageItem.StorageDimensionGroup, locationCache) ? '1' : '0'); json.Append(',');
        json.Append(!inventTable.ProductLifecycleStateId || inventTable.ProductLifecycleStateId == 'Active' ? '1' : '0'); json.Append(',');
        json.Append(HSMobileOpsSkuPageService::jsonStr(HSMobileOpsSkuPageService::pathOf(productCategory.Category, categoryPaths)));
        json.Append(']');
        last = inventTable.ItemId;
        rows++;
    }
    json.Append(']');
    _response.parmRowsJson(json.ToString());
    _response.parmRowCount(rows);
    _response.parmNextKey(last ? last : _after);
    _response.parmHasMore(more);
}

/// <summary>One row of the ITEMS feed of a store that syncs by assortment - the columns of itemPage.</summary>
private static void itemRow(System.Text.StringBuilder _json, InventTable _inventTable, UnitOfMeasureSymbol _inventUnit,
    UnitOfMeasureSymbol _purchUnit, UnitOfMeasureSymbol _salesUnit, container _tracking, boolean _location, str _category)
{
    _json.Append('[');
    _json.Append(HSMobileOpsSkuPageService::jsonStr(_inventTable.ItemId)); _json.Append(',');
    _json.Append(HSMobileOpsSkuPageService::jsonStr(_inventTable.NameAlias)); _json.Append(',');
    _json.Append(HSMobileOpsSkuPageService::jsonStr(_inventUnit)); _json.Append(',');
    _json.Append(HSMobileOpsSkuPageService::jsonStr(_purchUnit)); _json.Append(',');
    _json.Append(HSMobileOpsSkuPageService::jsonStr(_salesUnit)); _json.Append(',');
    _json.Append(conPeek(_tracking, 1) ? '1' : '0'); _json.Append(',');
    _json.Append(conPeek(_tracking, 2) ? '1' : '0'); _json.Append(',');
    _json.Append(_location ? '1' : '0'); _json.Append(',');
    _json.Append(!_inventTable.ProductLifecycleStateId || _inventTable.ProductLifecycleStateId == 'Active' ? '1' : '0'); _json.Append(',');
    _json.Append(HSMobileOpsSkuPageService::jsonStr(_category));
    _json.Append(']');
}

internal static void barcodePage(HSMobileOpsSkuPageResponse _response, RecId _after, utcdatetime _since, int _pageSize, RecId _upTo = 0, InventLocationId _scope = '')
{
    HSMobileOpsSyncAssortItem   scopeItem;
    InventItemBarcode           barcode;
    InventDim                   inventDim;
    InventTable                 inventTable;
    System.Text.StringBuilder   json = new System.Text.StringBuilder();
    int                         rows;
    RecId                       last;
    boolean                     more;
    boolean                     full = _since == DateTimeUtil::minValue();
    RecId                       upTo = _upTo ? _upTo : 0x7FFFFFFFFFFFFFFF;

    json.Append('[');
    if (_scope)
    {
        // A store that syncs by assortment: only its items' barcodes.
        while select itemBarCode, ItemId, Qty, UnitID, Blocked, RecId from barcode
            order by barcode.RecId
            where barcode.RecId            > _after
               && barcode.RecId            <= upTo
               && barcode.ModifiedDateTime >= _since
               && (!full || !barcode.Blocked)
            outer join configId, InventSizeId, InventColorId, InventStyleId from inventDim
                where inventDim.inventDimId == barcode.inventDimId
            exists join inventTable
                where inventTable.ItemId   == barcode.ItemId
                   && inventTable.ItemType != ItemType::Service
                   && (!full || !inventTable.ProductLifecycleStateId || inventTable.ProductLifecycleStateId == 'Active')
            exists join scopeItem
                where scopeItem.Warehouse == _scope
                   && scopeItem.ItemId    == barcode.ItemId
        {
            if (rows >= _pageSize)
            {
                more = true;
                break;
            }
            if (rows)
            {
                json.Append(',');
            }
            json.Append(HSMobileOpsSkuPageService::barcodeRow(barcode, inventDim));
            last = barcode.RecId;
            rows++;
        }
    }
    else
    while select itemBarCode, ItemId, Qty, UnitID, Blocked, RecId from barcode
        order by barcode.RecId
        where barcode.RecId            > _after
           && barcode.RecId            <= upTo
           && barcode.ModifiedDateTime >= _since
           && (!full || !barcode.Blocked)
        outer join configId, InventSizeId, InventColorId, InventStyleId from inventDim
            where inventDim.inventDimId == barcode.inventDimId
        // The item filter of itemPage, so no barcode points at an item the device does not have.
        exists join inventTable
            where inventTable.ItemId   == barcode.ItemId
               && inventTable.ItemType != ItemType::Service
               && (!full || !inventTable.ProductLifecycleStateId || inventTable.ProductLifecycleStateId == 'Active')
    {
        if (rows >= _pageSize)
        {
            more = true;
            break;
        }
        if (rows)
        {
            json.Append(',');
        }
        json.Append('[');
        json.Append(HSMobileOpsSkuPageService::jsonStr(barcode.itemBarCode)); json.Append(',');
        json.Append(HSMobileOpsSkuPageService::jsonStr(barcode.ItemId)); json.Append(',');
        json.Append(num2Str(barcode.Qty, 0, 6, 1, 0)); json.Append(',');
        json.Append(HSMobileOpsSkuPageService::jsonStr(barcode.UnitID)); json.Append(',');
        json.Append(HSMobileOpsSkuPageService::jsonStr(inventDim.configId)); json.Append(',');
        json.Append(HSMobileOpsSkuPageService::jsonStr(inventDim.InventSizeId)); json.Append(',');
        json.Append(HSMobileOpsSkuPageService::jsonStr(inventDim.InventColorId)); json.Append(',');
        json.Append(HSMobileOpsSkuPageService::jsonStr(inventDim.InventStyleId)); json.Append(',');
        json.Append(barcode.Blocked ? '1' : '0');
        json.Append(']');
        last = barcode.RecId;
        rows++;
    }
    json.Append(']');
    _response.parmRowsJson(json.ToString());
    _response.parmRowCount(rows);
    _response.parmNextKey(int642Str(last ? last : _after));
    _response.parmHasMore(more);
}

/// <summary>One row of the BARCODES feed of a store that syncs by assortment - the columns of barcodePage.</summary>
private static str barcodeRow(InventItemBarcode _barcode, InventDim _inventDim)
{
    System.Text.StringBuilder json = new System.Text.StringBuilder();

    json.Append('[');
    json.Append(HSMobileOpsSkuPageService::jsonStr(_barcode.itemBarCode)); json.Append(',');
    json.Append(HSMobileOpsSkuPageService::jsonStr(_barcode.ItemId)); json.Append(',');
    json.Append(num2Str(_barcode.Qty, 0, 6, 1, 0)); json.Append(',');
    json.Append(HSMobileOpsSkuPageService::jsonStr(_barcode.UnitID)); json.Append(',');
    json.Append(HSMobileOpsSkuPageService::jsonStr(_inventDim.configId)); json.Append(',');
    json.Append(HSMobileOpsSkuPageService::jsonStr(_inventDim.InventSizeId)); json.Append(',');
    json.Append(HSMobileOpsSkuPageService::jsonStr(_inventDim.InventColorId)); json.Append(',');
    json.Append(HSMobileOpsSkuPageService::jsonStr(_inventDim.InventStyleId)); json.Append(',');
    json.Append(_barcode.Blocked ? '1' : '0');
    json.Append(']');
    return json.ToString();
}

internal static void variantPage(HSMobileOpsSkuPageResponse _response, RecId _after, int _pageSize, InventLocationId _scope = '')
{
    HSMobileOpsSyncAssortItem   scopeItem;
    InventDimCombination        combination;
    InventDim                   inventDim;
    EcoResProductTranslation    translation;
    LanguageId                  language = CompanyInfo::languageId();
    System.Text.StringBuilder   json = new System.Text.StringBuilder();
    int                         rows;
    RecId                       last;
    boolean                     more;

    json.Append('[');
    if (_scope)
    {
        // A store that syncs by assortment: only its items' variants.
        while select ItemId, RecId, DistinctProductVariant from combination
            order by combination.RecId
            where combination.RecId > _after
            join configId, InventSizeId, InventColorId, InventStyleId from inventDim
                where inventDim.inventDimId == combination.InventDimId
            outer join Name from translation
                where translation.Product    == combination.DistinctProductVariant
                   && translation.LanguageId == language
            exists join scopeItem
                where scopeItem.Warehouse == _scope
                   && scopeItem.ItemId    == combination.ItemId
        {
            if (rows >= _pageSize)
            {
                more = true;
                break;
            }
            if (rows)
            {
                json.Append(',');
            }
            json.Append(HSMobileOpsSkuPageService::variantRow(combination, inventDim, translation));
            last = combination.RecId;
            rows++;
        }
    }
    else
    while select ItemId, RecId, DistinctProductVariant from combination
        order by combination.RecId
        where combination.RecId > _after
        join configId, InventSizeId, InventColorId, InventStyleId from inventDim
            where inventDim.inventDimId == combination.InventDimId
        // The variant's own name, in the company's language - the handheld's variant picker
        // showed only "Config C1". Outer: a variant without a translation still syncs.
        outer join Name from translation
            where translation.Product    == combination.DistinctProductVariant
               && translation.LanguageId == language
    {
        if (rows >= _pageSize)
        {
            more = true;
            break;
        }
        if (rows)
        {
            json.Append(',');
        }
        json.Append('[');
        json.Append(HSMobileOpsSkuPageService::jsonStr(combination.ItemId)); json.Append(',');
        json.Append(HSMobileOpsSkuPageService::jsonStr(inventDim.configId)); json.Append(',');
        json.Append(HSMobileOpsSkuPageService::jsonStr(inventDim.InventSizeId)); json.Append(',');
        json.Append(HSMobileOpsSkuPageService::jsonStr(inventDim.InventColorId)); json.Append(',');
        json.Append(HSMobileOpsSkuPageService::jsonStr(inventDim.InventStyleId)); json.Append(',');
        json.Append(HSMobileOpsSkuPageService::jsonStr(translation.Name));
        json.Append(']');
        last = combination.RecId;
        rows++;
    }
    json.Append(']');
    _response.parmRowsJson(json.ToString());
    _response.parmRowCount(rows);
    _response.parmNextKey(int642Str(last ? last : _after));
    _response.parmHasMore(more);
}

/// <summary>One row of the VARIANTS feed of a store that syncs by assortment - the columns of variantPage.</summary>
private static str variantRow(InventDimCombination _combination, InventDim _inventDim, EcoResProductTranslation _translation)
{
    System.Text.StringBuilder json = new System.Text.StringBuilder();

    json.Append('[');
    json.Append(HSMobileOpsSkuPageService::jsonStr(_combination.ItemId)); json.Append(',');
    json.Append(HSMobileOpsSkuPageService::jsonStr(_inventDim.configId)); json.Append(',');
    json.Append(HSMobileOpsSkuPageService::jsonStr(_inventDim.InventSizeId)); json.Append(',');
    json.Append(HSMobileOpsSkuPageService::jsonStr(_inventDim.InventColorId)); json.Append(',');
    json.Append(HSMobileOpsSkuPageService::jsonStr(_inventDim.InventStyleId)); json.Append(',');
    json.Append(HSMobileOpsSkuPageService::jsonStr(_translation.Name));
    json.Append(']');
    return json.ToString();
}

/// <summary>
/// The UNITS feed - see getSkuPage. A full refresh walks the released items as ITEMS does; a
/// delta walks only the items whose unit setup changed since _since.
/// </summary>
internal static void unitPage(HSMobileOpsSkuPageResponse _response, ItemId _after, utcdatetime _since, int _pageSize, ItemId _upTo = '', InventLocationId _scope = '')
{
    HSMobileOpsSyncAssortItem   scopeItem;
    InventTable                 inventTable;
    Map                         factors = new Map(Types::String, Types::Real);
    Map                         decimals = new Map(Types::String, Types::Integer);
    System.Text.StringBuilder   json = new System.Text.StringBuilder();
    boolean                     full = _since == DateTimeUtil::minValue();
    Set                         changed;
    SetEnumerator               itemEnum;
    int                         rows;
    ItemId                      last;
    boolean                     more;

    json.Append('[');
    if (full && _scope)
    {
        ItemId scopeUpTo = _upTo ? _upTo : HSMobileOpsSkuPageService::lastItemId();

        // A store that syncs by assortment: its item list drives the query.
        while select ItemId from scopeItem
            order by scopeItem.ItemId
            where scopeItem.Warehouse == _scope
               && scopeItem.ItemId    >  _after
               && scopeItem.ItemId    <= scopeUpTo
            join ItemId, Product from inventTable
                where inventTable.ItemId   == scopeItem.ItemId
                   && inventTable.ItemType != ItemType::Service
                   && (!inventTable.ProductLifecycleStateId || inventTable.ProductLifecycleStateId == 'Active')
        {
            if (rows >= _pageSize)
            {
                more = true;
                break;
            }
            if (rows)
            {
                json.Append(',');
            }
            json.Append(HSMobileOpsSkuPageService::unitRow(inventTable, factors, decimals));
            last = inventTable.ItemId;
            rows++;
        }
    }
    else if (full)
    {
        ItemId upTo = _upTo ? _upTo : HSMobileOpsSkuPageService::lastItemId();

        while select ItemId, Product from inventTable
            order by inventTable.ItemId
            where inventTable.ItemId > _after
               && inventTable.ItemId <= upTo
               && inventTable.ItemType != ItemType::Service
               && (!inventTable.ProductLifecycleStateId || inventTable.ProductLifecycleStateId == 'Active')
        {
            if (rows >= _pageSize)
            {
                more = true;
                break;
            }
            if (rows)
            {
                json.Append(',');
            }
            json.Append(HSMobileOpsSkuPageService::unitRow(inventTable, factors, decimals));
            last = inventTable.ItemId;
            rows++;
        }
    }
    else
    {
        // A Set enumerates in key order, so paging by ItemId works as for a full refresh.
        changed = HSMobileOpsSkuPageService::unitChangesSince(_since);
        itemEnum = changed.getEnumerator();
        while (itemEnum.moveNext())
        {
            if (itemEnum.current() <= _after)
            {
                continue;
            }
            if (rows >= _pageSize)
            {
                more = true;
                break;
            }
            if (_scope && !HSMobileOpsSyncAssortItem::exist(_scope, itemEnum.current()))
            {
                continue;
            }
            inventTable = InventTable::find(itemEnum.current());
            if (!inventTable.RecId || inventTable.ItemType == ItemType::Service)
            {
                continue;
            }
            if (rows)
            {
                json.Append(',');
            }
            json.Append(HSMobileOpsSkuPageService::unitRow(inventTable, factors, decimals));
            last = inventTable.ItemId;
            rows++;
        }
    }
    json.Append(']');
    _response.parmRowsJson(json.ToString());
    _response.parmRowCount(rows);
    _response.parmNextKey(last ? last : _after);
    _response.parmHasMore(more);
}

/// <summary>
/// Items whose unit setup changed since _since: their units (InventTableModule), their
/// product-specific conversions, or a barcode with a unit. A change to a standard conversion
/// reaches the devices with their weekly full refresh.
/// </summary>
private static Set unitChangesSince(utcdatetime _since)
{
    Set                     items = new Set(Types::String);
    InventTableModule       module;
    UnitOfMeasureConversion conversion;
    InventTable             inventTable;
    InventItemBarcode       barcode;

    while select ItemId from module
        group by module.ItemId
        where module.ModifiedDateTime >= _since
    {
        items.add(module.ItemId);
    }
    while select Product from conversion
        group by conversion.Product
        where conversion.Product          != 0
           && conversion.ModifiedDateTime >= _since
    {
        while select ItemId from inventTable
            where inventTable.Product == conversion.Product
        {
            items.add(inventTable.ItemId);
        }
    }
    while select ItemId from barcode
        group by barcode.ItemId
        where barcode.ModifiedDateTime >= _since
           && barcode.UnitID
    {
        items.add(barcode.ItemId);
    }
    return items;
}

/// <summary>
/// One UNITS row. Factors between two units with no product-specific conversion are the same
/// for every item, so they are worked out once per feed page (_factors).
/// </summary>
private static str unitRow(InventTable _inventTable, Map _factors, Map _decimals)
{
    System.Text.StringBuilder   json = new System.Text.StringBuilder();
    UnitOfMeasureConversion     conversion;
    InventItemBarcode           barcode;
    EcoResProductUnitConverter  converter;
    Set                         candidates = new Set(Types::String);
    SetEnumerator               se;
    str                         inventUnit = _inventTable.inventUnitId();
    str                         purchUnit  = _inventTable.purchUnitId();
    str                         salesUnit  = _inventTable.salesUnitId();
    str                         unit;
    str                         key;
    boolean                     own;
    real                        factor;
    real                        inverse;
    int                         units;

    candidates.add(inventUnit);
    candidates.add(purchUnit);
    candidates.add(salesUnit);
    while select FromUnitOfMeasure, ToUnitOfMeasure from conversion
        where conversion.Product == _inventTable.Product
    {
        own = true;
        candidates.add(UnitOfMeasure::find(conversion.FromUnitOfMeasure).Symbol);
        candidates.add(UnitOfMeasure::find(conversion.ToUnitOfMeasure).Symbol);
    }
    while select UnitID from barcode
        group by barcode.UnitID
        where barcode.itemId == _inventTable.ItemId
           && barcode.UnitID
    {
        candidates.add(barcode.UnitID);
    }

    json.Append('[');
    json.Append(HSMobileOpsSkuPageService::jsonStr(_inventTable.ItemId)); json.Append(',');
    json.Append(HSMobileOpsSkuPageService::jsonStr(inventUnit)); json.Append(',');
    json.Append(HSMobileOpsSkuPageService::jsonStr(purchUnit)); json.Append(',');
    json.Append(HSMobileOpsSkuPageService::jsonStr(salesUnit)); json.Append(',[');
    se = candidates.getEnumerator();
    while (se.moveNext())
    {
        unit = se.current();
        if (!unit || !inventUnit)
        {
            continue;
        }
        factor = 0;
        if (unit == inventUnit)
        {
            factor = 1;
        }
        else
        {
            key = unit + '>' + inventUnit;
            if (!own && _factors.exists(key))
            {
                factor = _factors.lookup(key);
            }
            else
            {
                converter = EcoResProductUnitConverter::newGivenUnitSymbolsForReleasedProduct(
                    _inventTable.ItemId, InventDim::inventDimIdBlank(), unit, inventUnit, NoYes::No, NoYes::No);
                if (converter.canValueBeConverted())
                {
                    factor = converter.convertValue(1);
                    // A factor below 1 (1 pcs = 0.0833 dz) loses digits; the reverse is exact.
                    if (factor > 0 && factor < 1)
                    {
                        converter = EcoResProductUnitConverter::newGivenUnitSymbolsForReleasedProduct(
                            _inventTable.ItemId, InventDim::inventDimIdBlank(), inventUnit, unit, NoYes::No, NoYes::No);
                        inverse = converter.canValueBeConverted() ? converter.convertValue(1) : 0;
                        if (inverse > 0)
                        {
                            factor = 1 / inverse;
                        }
                    }
                }
                if (!own)
                {
                    _factors.insert(key, factor);
                }
            }
        }
        if (factor <= 0)
        {
            continue;
        }
        if (!_decimals.exists(unit))
        {
            _decimals.insert(unit, UnitOfMeasure::findBySymbol(unit).DecimalPrecision);
        }
        if (units)
        {
            json.Append(',');
        }
        json.Append('[');
        json.Append(HSMobileOpsSkuPageService::jsonStr(unit)); json.Append(',');
        json.Append(num2Str(factor, 0, 10, 1, 0)); json.Append(',');
        json.Append(int2Str(_decimals.lookup(unit)));
        json.Append(']');
        units++;
    }
    json.Append(']]');
    return json.ToString();
}

/// <summary>[batch active, serial active] of a tracking dimension group - looked up once per group per page.</summary>
private static container trackingFlags(RefRecId _group, Map _cache)
{
    EcoResTrackingDimensionGroupFldSetup setup;
    boolean batch;
    boolean serial;

    if (!_group)
    {
        return [false, false];
    }
    if (_cache.exists(_group))
    {
        return _cache.lookup(_group);
    }
    while select DimensionFieldId, IsActive from setup
        where setup.TrackingDimensionGroup == _group
           && setup.IsActive               == NoYes::Yes
    {
        if (setup.DimensionFieldId == fieldNum(InventDim, InventBatchId))
        {
            batch = true;
        }
        if (setup.DimensionFieldId == fieldNum(InventDim, InventSerialId))
        {
            serial = true;
        }
    }
    _cache.insert(_group, [batch, serial]);
    return [batch, serial];
}

/// <summary>Whether a storage dimension group has the location active - looked up once per group per page.</summary>
private static boolean locationActive(RefRecId _group, Map _cache)
{
    EcoResStorageDimensionGroupFldSetup setup;
    int active;

    if (!_group)
    {
        return true;
    }
    if (_cache.exists(_group))
    {
        return _cache.lookup(_group) == 1;
    }
    select firstonly RecId from setup
        where setup.StorageDimensionGroup == _group
           && setup.DimensionFieldId      == fieldNum(InventDim, wMSLocationId)
           && setup.IsActive              == NoYes::Yes;
    active = setup.RecId ? 1 : 0;
    _cache.insert(_group, active);
    return active == 1;
}

/// <summary>The company's retail product hierarchy - where an item's category comes from.</summary>
private static RefRecId retailHierarchy()
{
    EcoResCategoryHierarchyRole role;

    select firstonly CategoryHierarchy from role
        where role.NamedCategoryHierarchyRole == EcoResCategoryNamedHierarchyRole::Retail;
    return role.CategoryHierarchy;
}

/// <summary>
/// A category of the hierarchy as a path from the first level down ("Health Care > Vitamins");
/// blank for none. Worked out once per category per page.
/// </summary>
private static str pathOf(RefRecId _category, Map _paths)
{
    EcoResCategory category;
    RefRecId       current = _category;
    str            path;
    int            depth;

    if (!_category)
    {
        return '';
    }
    if (_paths.exists(_category))
    {
        return _paths.lookup(_category);
    }
    while (current && depth < 10)
    {
        depth++;
        select firstonly RecId, Name, Level, ParentCategory from category
            where category.RecId == current;
        // Level 1 is the hierarchy's root, which names the hierarchy, not a category.
        if (!category.RecId || category.Level < 2)
        {
            break;
        }
        path = path ? category.Name + ' > ' + path : category.Name;
        current = category.ParentCategory;
    }
    _paths.insert(_category, path);
    return path;
}

/// <summary>
/// The CATEGORIES feed - see getSkuPage. Category changes do not touch InventTable, so a
/// delta of ITEMS missed them (user, 13 Nov).
/// </summary>
private static void categoryPage(HSMobileOpsSkuPageResponse _response, RecId _after, utcdatetime _since, int _pageSize, InventLocationId _scope = '')
{
    HSMobileOpsSyncAssortItem scopeItem;
    EcoResProductCategory     productCategory;
    EcoResCategory            changedCategory;
    InventTable               inventTable;
    Map                       paths = new Map(Types::Int64, Types::String);
    RefRecId                  hierarchy = HSMobileOpsSkuPageService::retailHierarchy();
    System.Text.StringBuilder json = new System.Text.StringBuilder();
    boolean                   treeChanged;
    int                       rows;
    RecId                     last;
    boolean                   more;

    json.Append('[');
    // A full sync gets the category with each item; nothing to add.
    if (_since != DateTimeUtil::minValue() && hierarchy)
    {
        select firstonly RecId from changedCategory
            where changedCategory.CategoryHierarchy == hierarchy
               && changedCategory.ModifiedDateTime  >= _since;
        treeChanged = changedCategory.RecId != 0;

        if (_scope)
        {
            // A store that syncs by assortment: only its items.
            while select RecId, Category from productCategory
                order by productCategory.RecId
                where productCategory.RecId             > _after
                   && productCategory.CategoryHierarchy == hierarchy
                   && (treeChanged || productCategory.ModifiedDateTime >= _since)
                join ItemId from inventTable
                    where inventTable.Product  == productCategory.Product
                       && inventTable.ItemType != ItemType::Service
                exists join scopeItem
                    where scopeItem.Warehouse == _scope
                       && scopeItem.ItemId    == inventTable.ItemId
            {
                if (rows >= _pageSize)
                {
                    more = true;
                    break;
                }
                if (rows)
                {
                    json.Append(',');
                }
                json.Append('[');
                json.Append(HSMobileOpsSkuPageService::jsonStr(inventTable.ItemId)); json.Append(',');
                json.Append(HSMobileOpsSkuPageService::jsonStr(HSMobileOpsSkuPageService::pathOf(productCategory.Category, paths)));
                json.Append(']');
                last = productCategory.RecId;
                rows++;
            }
        }
        else
        while select RecId, Category from productCategory
            order by productCategory.RecId
            where productCategory.RecId             > _after
               && productCategory.CategoryHierarchy == hierarchy
               && (treeChanged || productCategory.ModifiedDateTime >= _since)
            join ItemId from inventTable
                where inventTable.Product  == productCategory.Product
                   && inventTable.ItemType != ItemType::Service
        {
            if (rows >= _pageSize)
            {
                more = true;
                break;
            }
            if (rows)
            {
                json.Append(',');
            }
            json.Append('[');
            json.Append(HSMobileOpsSkuPageService::jsonStr(inventTable.ItemId)); json.Append(',');
            json.Append(HSMobileOpsSkuPageService::jsonStr(HSMobileOpsSkuPageService::pathOf(productCategory.Category, paths)));
            json.Append(']');
            last = productCategory.RecId;
            rows++;
        }
    }
    json.Append(']');
    _response.parmRowsJson(json.ToString());
    _response.parmRowCount(rows);
    _response.parmNextKey(int642Str(last ? last : _after));
    _response.parmHasMore(more);
}

internal static str jsonStr(str _value)
{
    str value = _value;

    value = strReplace(value, '\\', '\\\\');
    value = strReplace(value, '"', '\\"');
    value = strReplace(value, '\n', '\\n');
    value = strReplace(value, '\r', '\\r');
    value = strReplace(value, '\t', '\\t');
    return '"' + value + '"';
}
